from pathlib import Path
import json, hashlib
from collections import Counter
import sys
ROOT=Path(__file__).resolve().parents[2]
sys.path[:0]=[str(ROOT/'src'),str(ROOT)]
from tools.compare_evacuation_modes_v2 import input_fingerprint

def load(path):return json.loads((ROOT/path).read_text(encoding='utf-8'))
def fmt(x):return f'{x:.4f}' if isinstance(x,float) else str(x)
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(fmt,row))+' |' for row in rows])

def write():
 report=load('reports/evacuation_comparison_v3/summary.json');before=load('reports/evacuation_comparison_v2/summary.json')
 perf=load('reports/septima_fase/performance_after.json');oldperf=load('reports/sexta_fase/performance_after.json')
 new_test_count=next(s['unit_tests'] for s in load('reports/septima_fase/tests_final/results.json')['scripts'] if s['script']=='tests/test_seventh_functional_changes.py')
 tests=load('reports/septima_fase/tests_final/results.json')['summary'];visual=load('reports/septima_fase/visual_verification.json')
 config=load('data/functional_scenario.json');exitdata=load('reports/septima_fase/exit_redundancy.json')
 assert report['complete'] and len(report['scenarios'])==16
 assert report.get('final_source_hash', report['source_hash'])==perf['source_hash']==visual['source_hash']==input_fingerprint()
 assert perf['headless_backend_gui_modules']==[]
 if report['source_hash']!=report['final_source_hash']:
  assert report['validated_ui_only_revision']['backend_and_all_data_unchanged']
 assert tests['failed_scripts']==0 and tests['skipped']==0
 assert all(c['identical_physical_trajectory'] for c in report['scenarios'])
 integrity=load('reports/septima_fase/protected_integrity.json')
 assert integrity['source_hash']==report['source_hash'] and all(integrity['files'].values())
 assert all(integrity['preserved_hazard_impact_classes_ast'].values())
 oldhash=load('reports/septima_fase/before_hashes.json')
 changed=[name for name,h in oldhash.items() if hashlib.sha256((ROOT/name).read_bytes()).hexdigest()!=h]
 oldconfig=load('reports/septima_fase/before/data/functional_scenario.json')
 assert all(config[k]==v for k,v in oldconfig.items())
 assert not any(n.startswith('data/functional/') for n in changed)
 t,i=report['aggregate']['traditional'],report['aggregate']['intelligent'];ib=before['aggregate']['intelligent']
 gates=report['readiness_checks'];state='READY' if all(v is True for v in gates.values()) else 'PARTIALLY READY'
 cases=report['scenarios'];traces=[e for c in cases for e in c['intelligent']['fire_contact_traces']]
 buildings=Counter(e['building'] or 'EXTERIOR' for e in traces);categories=Counter(e['category'] for e in traces)
 oldcases={c['scenario_id']:c for c in before['scenarios']}
 unchanged=True
 for c in cases:
  old=oldcases[c['scenario_id']]
  assert {k:v for k,v in c.items() if k not in ('traditional','intelligent','identical_physical_trajectory')}=={k:v for k,v in old.items() if k not in ('traditional','intelligent','identical_physical_trajectory')}
  assert c['traditional']['physical_trajectory']==old['traditional']['physical_trajectory']
  unchanged &= all(v==c['traditional']['metrics'][k] for k,v in old['traditional']['metrics'].items() if k!='runtime_seconds')
 assert unchanged
 metric_names=['safe_meeting_arrivals','people_exposed_smoke','accumulated_smoke_dose','people_close_to_fire','fire_contacts','interior_fire_contacts','exterior_fire_contacts','next_turn_fire_escapes','incapacitated','unsafe_waiting_person_turns','unassigned','routes_recalculated','distance_traveled','destination_became_unsafe_before_arrival','SafetyScore','runtime_seconds']
 sections=[]
 def s(title,text):sections.append('## '+title+'\n\n'+text.strip()+'\n')
 s('1. Resumen',f"Séptima fase implementada: prevención interior, refugios compartidos, prioridad por redundancia de salidas y vista pública en español. Estado **{state}** según mediciones, no solo tests. No se cambió física, población, puertas ni benchmark. Rama `codex/septima-fase-funcional`; sin commits ni push.")
 s('2. Diagnóstico final de fire contacts interiores',f"La sexta fase registró 47 contactos Intelligent: 46 durante peligro → exposición, antes de movimiento, y uno ya sobre el foco inicial. No eran pasos exteriores de A* hacia fuego. E16 tenía el mayor problema: 18 y 15 contactos en S02/S16; E53 diez; E15 cuatro. El refugio local de menor coste podía terminar junto a un borde sin vía de salida.\n\nEn la versión final se observaron {len(traces)} contactos Intelligent, distribuidos por edificio: `{dict(buildings)}`. Categorías: `{dict(categories)}`. Cada checkpoint conserva turno, alumno, posición, edificio y diagnóstico previo. ExposureTracker conserva su estado absorbente: no vuelve a sumar contactos a personas ya incapacitadas. No se eliminó ni redefinió fire_contacts. Además se reprodujo una inversión de prioridad: A, urgente en5,3, esperaba por B en4,3; B avanzaba después a3,3 y dejaba un paso seguro libre, pero A no volvía a intentarlo. Eso desperdiciaba su única oportunidad antes del siguiente fuego. Evidencia: priority_inversion_reproduction.json. La corrección final resuelve estas dependencias dentro del mismo turno. El foco sobre P232 de S07 sigue presente; el orden físico impide deshacer esa exposición inicial.")
 s('3. NextTurnFireThreat',"`src/simulation/next_turn_fire.py` observa fuego activo y vecinos cardinales actualmente combustibles. Usa `ScenarioFireSimulation.spread_probability`, incluidos multiplicadores de combustible/laboratorio y viento real. Propaga una aproximación de unión por caminos locales durante tres iteraciones; no es una probabilidad calibrada ni conoce sorteos futuros. Fuentes que pueden agotarse se conservan de forma precautoria en ese horizonte corto.\n\nFIRE_NOW identifica fuego actual; FIRE_FRONTIER identifica celdas todavía libres con score >=0.025; SAFE queda fuera de ambos. Brasas aportan probabilidad de propuesta uniforme sobre los offsets direccionales reales, con distancia acotada, sin consultar ni avanzar RNG; no se interpreta el cupo global como una certeza de ignición. Caminos/reuniones no combustibles y celdas quemadas no reciben nuevas igniciones previstas. El campo es compartido por turno y se calcula también en Traditional para observación simétrica; solo Intelligent lo usa en decisiones. El overlay amarillo aparece exclusivamente en Debug.")
 sections[-1] += "\n\nConfiguración añadida:\n\n```json\n"+json.dumps({k:config[k] for k in ("interior_prediction","presentation")},ensure_ascii=False,indent=2)+"\n```\n"
 s('4. Evacuación interior predictiva',"AdaptiveExitController sigue siendo la autoridad de movimiento interior. Tras actualizar peligro/exposición, calcula amenaza para el siguiente avance y mueve ahora a los alumnos móviles. Se conserva exterior primero, interior después y máximo una celda por turno. No hay movimiento preventivo extra antes de la física ni excepción a ralentización/incapacidad.\n\nLa política `PredictiveInteriorPolicy` añade +2400 a ocupantes del frente. Descarta destinos con fuego, frente preventivo, fire ETA <=3 o humo >=0.65. Entre pasos hacia una salida elige determinísticamente el potencial compartido más coste de probabilidad y humo. Dosis personal, smoke ETA y fire ETA intervienen mediante la prioridad/diagnóstico existente; el refugio penaliza humo actual y previsto. Si falta potencial a salida, busca refugio conectado; ante amenaza inminente permite abandonar el origen hacia un vecino con mayor fire ETA aunque no exista ruta completa. Espera si no hay paso seguro útil. No hay movimiento aleatorio ni un segundo A*.")
 sections[-1] += '\n\nResolución de dependencias: después de la pasada principal se reintenta solo a alumnos elegibles que todavía no se movieron, en edificios amenazados. Se reutiliza _move_indoor_person para el paso autorizado. Una cola despierta a quien esperaba una celda cuando su vecino la libera. Cada alumno puede moverse una sola vez; cada uno tiene cuatro vecinos, por lo que el trabajo queda acotado por alumnos y vacantes, no por parejas de celdas. No cambia el orden peligro → exposición → exterior → interior → métricas ni se añade otro turno. La elegibilidad de ralentización/incapacidad se conserva. Traditional y legacy tienen finalización vacía. Las pruebas comparan resolución activada/desactivada en el mismo corredor y comprueban ausencia de segundo paso y bloqueo ante celdas peligrosas.'
 s('5. Refugio interior temporal',"`InteriorSafeIntermediateGoal` usa componentes interiores seguras, vecindad estática precalculada y un campo compartido por componente/edificio/turno. No busca desde cada alumno por todo el campus.\n\nCalidad de celda = `3*min(60, distancia_fuego) + min(60, fire_eta) - 30*humo - 12*plume + grado`. Se prefieren celdas con al menos dos vecinos en la componente y conexión geométrica estática a una puerta registrada. Solo si no existe una opción ramificada se considera el resto. Semillas: cuartil superior de candidatos libres (fracción0.25), ampliado hasta ofrecer al menos una celda por alumno móvil pendiente del edificio si hay espacio. Se excluyen celdas ocupadas. La calidad del campo es el límite inferior de las metas ofrecidas; así la condición de mejora mínima sigue siendo real. Esta diversidad evita conducir a toda una clase hacia un único máximo en una esquina. El potencial hacia ellas usa pasos cardinales con coste `1+30*humo`. Se exige mejora de calidad >=2, salvo escape inminente con mayor fire ETA. Ocupación y bloqueo se vuelven a comprobar antes de mover.\n\nLa conexión estática no garantiza que una puerta se reabra: no se atraviesa fuego para alcanzarla. Los refugios son temporales, no reuniones ni alumnos a salvo. Los campos se reconstruyen por turno cuando se necesitan; no se cambia la geometría.")
 s('6. Riesgo por redundancia de salidas',f"Se agrupan pares finos por ID fuente, quitando el sufijo `-sub`. Tres subceldas de la misma puerta no son tres salidas alternativas. Hay {len(exitdata['single_exit_buildings'])} edificios con un grupo. Cuando alguna celda del edificio está a <=22 celdas del fuego, un grupo añade +450; dos grupos +120; tres o más no añaden esta urgencia. Sin amenaza no hay bonificación. Se mantienen laboratorio, dosis, margen y antigüedad de sexta fase. Un test verifica que la prioridad real de E16 llega al controlador, no solo a un JSON. Esta prioridad ordena el controlador existente; no adelanta la alarma, añade turnos de movimiento ni aumenta la capacidad física de una puerta. Todos los alumnos ya empiezan a evacuar al activar A.\n\nLista de un grupo: "+', '.join(exitdata['single_exit_buildings'])+".\n\nArchivo diagnóstico: `reports/septima_fase/exit_redundancy.json`. No se añadieron puertas.")
 observed_single=sorted(set(perf['interior_prediction']['observed_redundancy_prioritized_buildings']) & set(exitdata['single_exit_buildings']))
 sections[-1] += f"\n\nEn el episodio aislado con focoE30 se registró prioridad estructural para {observed_single} (un grupo) y también E28 (dos grupos). La prueba controlada de E16 verifica por separado su entrada prioritaria al controlador. La lista completa es una política condicional, no una afirmación de que los41 edificios estuvieron amenazados en cada episodio."
 s('7. Fire contacts antes/después',table(['Media de 16','Traditional sexta','Intelligent sexta','Traditional séptima','Intelligent séptima'],[['fire_contacts',2.5,2.9375,t['fire_contacts']['mean'],i['fire_contacts']['mean']]])+f"\n\nTotales nuevos T/I: {sum(c['traditional']['metrics']['fire_contacts'] for c in cases)} / {len(traces)}. Los nuevos contadores separan contacto interior/exterior según posición en el primer contacto. `next_turn_fire_escapes` cuenta episodios persona/celda/turno: abandona una celda interior que era frontera y esa celda se observa ardiendo entre 1 y 3 turnos después, estando la persona fuera de ella. Una mera predicción, un replan o una salida no confirmada no incrementan el contador. No cuenta personas únicas ni vidas salvadas. Tampoco es un contador que deba maximizarse: evitar el frente antes de ocuparlo puede reducirlo. Media observada T/I: {t['next_turn_fire_escapes']['mean']:.4f} / {i['next_turn_fire_escapes']['mean']:.4f}.")
 s('8. Benchmark Traditional vs Intelligent',"Se reejecutaron los 32 episodios, 16 escenarios × dos modos ×160 turnos =5120 turnos. Son exactamente las definiciones de sexta fase, incluidos E16, E15, humo persistente, dos reuniones amenazadas y salida principal bloqueada. Misma población/posiciones, foco(s), puertas, seed, viento y orden físico por par. Se verificaron 161 hashes físicos por caso, ocupación única y desplazamiento <=1. Todas las métricas históricas Traditional, excluyendo tiempo de reloj, coinciden exactamente con sexta fase.\n\n"+table(['Métrica, media','Traditional','Intelligent'],[[k,t[k]['mean'],i[k]['mean']] for k in metric_names])+"\n\n"+table(['Caso','Edificio','Contactos T/I','Incapacitados T/I','Sin ruta T/I'],[[c['scenario_id'],c['building'],str(c['traditional']['metrics']['fire_contacts'])+'/'+str(c['intelligent']['metrics']['fire_contacts']),str(c['traditional']['metrics']['incapacitated'])+'/'+str(c['intelligent']['metrics']['incapacitated']),str(c['traditional']['metrics']['unassigned'])+'/'+str(c['intelligent']['metrics']['unassigned'])] for c in cases])+"\n\nReportes: `reports/evacuation_comparison_v3/summary.json`, `summary.csv`, `per_scenario.csv` y 32 checkpoints. Se conservaron sexta/v2 y los ensayos preliminares separados. El hash source_hash conserva la versión realmente ejecutada. Después del benchmark se pulieron exclusivamente tres archivos de interfaz: tarjeta Debug, SafetyScore solo Debug y tecla + de teclado español. Un manifiesto previo verifica que todos los módulos del backend, todos los JSON y el ejecutor/digest permanecen idénticos; final_source_hash identifica esa revisión visual, probada y renderizada por separado. La medición aislada confirma que el backend sin interfaz no importa dcc_app. --finalize-only adjunta esta evidencia sin cambiar métricas ni presentar ejecuciones antiguas como nuevas.")
 s('9. Rendimiento',f"Protocolo aislado: 240 turnos, administrador optimizado, Intelligent, seed2026, foco235166, vientoE0.75, sin UI ni assertions dentro del bucle cronometrado. Sexta: {oldperf['seconds_per_turn']:.6f} s/turno. Primera implementación séptima:0.805636. Versión final:{perf['seconds_per_turn']:.6f} s/turno; total {perf['elapsed_seconds']:.3f}s, inicio {perf['initialization_seconds']:.3f}s. Hash físico final igual al anterior: `{perf['physics_digest']}`.\n\nEl profiler detectó doble validación del mismo fuego/ruta y conversiones repetidas a NumPy. Se reutiliza el margen dentro de la misma decisión y se guardan coordenadas por alumno/firma de contenido. Se recalcula el margen con el campo vigente en TODOS los puntos restantes; una mutación de ruta invalida coordenadas, una mutación de peligro se lee de nuevo. No se guardan veredictos de seguridad entre turnos. Se conservaron A*, congestión y watchdog. Los tests comparan exactamente caché versus validación completa.\n\nEl perfil se toma aparte en cinco turnos60–64; su overhead no se presenta como tiempo aislado. Los tiempos de workers del benchmark incluyen contención por tres procesos, assertions y hashes; al principio también coincidieron con pruebas/capturas. No son un ensayo de rendimiento puro. Los dos modos comparten las entradas físicas, no se presume igual carga de CPU instantánea; no se usan como medición aislada de rendimiento. Detalle: `reports/septima_fase/profile_after.txt` y `performance_after.json`.")
 sections[-1] += f"\n\nIncremento aislado respecto a sexta: {(perf['seconds_per_turn']/oldperf['seconds_per_turn']-1)*100:.2f}%; cumple <=0.75s/turno, pero no se presenta como una aceleración frente a sexta. En este episodio de240 turnos, fire_contacts pasó {oldperf['metrics']['fire_contacts']}→{perf['metrics']['fire_contacts']}, incapacitados {oldperf['metrics']['incapacitated']}→{perf['metrics']['incapacitated']}, sin asignación {oldperf['metrics']['unassigned']}→{perf['metrics']['unassigned']} y replans {oldperf['metrics']['routes_recalculated']}→{perf['metrics']['routes_recalculated']}. El aumento aislado de sin asignación sigue visible, aunque la media de los16 escenarios mejora. A* totales={perf['total_astar_searches']}, guía hits={perf['cache_hits']}, misses={perf['cache_misses']}, usos={perf['flow_field_usage']}. La captura del resumen se produce después del intervalo medido."
 s('10. Presentation Mode',"Vista predeterminada de la misma aplicación, sin panel lateral técnico. Ventana1320×830 conservada, mapa de ancho completo entre cabecera compacta y footer. Texto principal en español, contraste alto y fuentes18–25. Los alumnos conservan sus celdas; el marcador añade un borde fino para distinguirlos. No se cambió el mapa ni sus colores generales.")
 s('11. Debug Mode',"D cambia a la disposición técnica existente y D otra vez vuelve. Solo cambia visualización/cámara; no muta decisiones, estado físico ni población. Mantiene sensores, ETA, margen, predictor, prioridades exteriores, motivos y overlay de riesgo. Frente preventivo en amarillo; riesgo/humo previsto en rojo. El ensayo envía eventos KEYDOWN reales dentro del bucle y verifica False→True→False con física/posiciones idénticas. La inspección técnica larga conserva las limitaciones de espacio del panel histórico. SafetyScore numérico aparece solo aquí. Al seleccionar un alumno Traditional se consultan ETA ambientales reales; margen/prioridad personal inexistentes se indican sin cálculo, no se inventan valores. El texto técnico de selección usa fuente12 para caber.")
 s('12. HUD final',"Arriba: título, MODO INTELIGENTE/TRADICIONAL y flecha de viento. Debajo: cuatro categorías de alumnos y reuniones disponibles. Última fila compacta: niveles de incendio/humo, velocidad del viento y estado de pausa/inicio. Abajo: solo controles sencillos y mensaje de tortugas. El mapa es protagonista. Al pausar desde turno240 aparece un resumen pequeño; no detiene por sí solo la física ni declara terminada una evacuación incompleta.")
 s('13. Datos mostrados',"Modo; dirección del viento; velocidad LENTO/MEDIO/RÁPIDO con valor normalizado pequeño; EN ZONA SEGURA; EVACUANDO; DENTRO; INCAPACITADOS; nivel de incendio; nivel de humo; reuniones disponibles/total. Son aproximadamente diez datos, más estado/controles.\n\nLos cuatro conteos son disjuntos y suman1879: incapacitados primero, después interiores, residentes móviles de reunión disponible y resto exterior. Una reunión AVOID/CLOSED nunca se presenta como segura, incluso si Traditional aún conserva allí un destino. Es observación visual, no cambio de política Traditional ni sustitución de métricas históricas. EN ZONA SEGURA no es certificación ni vidas salvadas.\n\nIncendio: BAJO<20 celdas activas, MEDIO20–99, ALTO>=100. Humo: BAJO<150 celdas con concentración>=0.05, MEDIO150–999, ALTO>=1000. Viento LENTO<0.33, MEDIO<0.66, RÁPIDO>=0.66. Umbrales configurables en `presentation`; no cambian física.")
 s('14. Datos técnicos ocultados',"Presentation no dibuja ETA de peligro/fuego/humo/dosis, márgenes, Ridge/persistencia, vectoresu/v, SafetyScore numérico, presupuestos, caches, scorings, IDs de alumnos, coordenadas ni versiones de schema. Los edificios E# y reuniones R# se conservan como referencias útiles. La lógica y métricas originales siguen disponibles en Debug y reportes.")
 s('15. Estados de zonas en español',"SAFE→SEGURA (verde); CAUTION→PRECAUCIÓN (amarillo); AVOID→EVITAR (naranja); CLOSED→CERRADA (rojo). Los Enum/contratos internos mantienen sus nombres. Estados de alumno: ESPERANDO, EVACUANDO, EN ZONA SEGURA, INCAPACITADO.")
 s('16. Mensajes inteligentes',"Máximo tres mensajes, duración3.5s de reloj, agregados una vez por turno y por tipo. Ejemplos reales de adaptador: «18 alumnos ajustaron su ruta para evacuar», «Salida bloqueada: buscando otra», «Alumnos alejándose del incendio dentro del edificio». Los cambios de zona se cuentan solo si origen y destino son reuniones reales; no se confunde cualquier replan preventivo con cambio de reunión. Los mensajes evitan causas específicas que no estén registradas. No se muestran eventos individuales repetidos ni texto técnico.")
 s('17. Selección de alumno',"Clic después de A usa la cámara/viewport/zoom actuales y selecciona el alumno cercano. Presentation muestra Alumno, estado en español, destino ZonaR# o búsqueda, y contexto/motivo traducido cuando existe. No muestra ID, ETA ni margen. Debug conserva diagnóstico técnico. Antes de A el clic sigue seleccionando el foco; después nunca crea fuego. Rueda y botón derecho conservan zoom/desplazamiento.")
 s('18. Captura/verificación visual',"`tools/render_presentation.py` renderiza SDL real con backenddummy a1320×830, turno40,1879 alumnos. Capturas inspeccionadas: `reports/septima_fase/presentation.png`, `presentation_student.png`, `debug.png`, `presentation_return.png` y `episode_summary.png` (pausa al turno240). El HUD público no tiene texto superpuesto, caben los cuatro conteos y el footer completo; el mapa permanece visible. El panel de alumno aparece solo al seleccionarlo. `visual_verification.json` guarda textos públicos, hash, resolución y la prueba de D sin cambios físicos. El backenddummy verifica render y eventos, no prueba un proyector ni interacción humana prolongada.")
 s('19. Archivos creados',"- `src/simulation/next_turn_fire.py`: frente preventivo compartido.\n- `src/simulation/interior_prediction.py`: decisiones/refugios del controlador interior.\n- `src/dcc_app/presentation_view.py`: traducciones, conteos y mensajes públicos.\n- `tests/test_seventh_functional_changes.py`: pruebas específicas.\n- `tools/compare_evacuation_modes_v3.py`: reutiliza los mismos escenarios/ejecutor y separa reportes séptimos.\n- `tools/render_presentation.py`: capturas y D real.\n- `SEVENTH_FUNCTIONAL_CHANGES_FEEDBACK.md`: este documento.\n\nLos reportes/snapshots son locales en `reports/` e ignorados por Git.")
 s('20. Archivos modificados',"- `src/simulation/functional_scenario.py`: enlaza máscara y prioridad interior sin reordenar física.\n- `src/simulation/hazard_impact.py`: extrae un único paso interior reutilizable y un hook de finalización vacío por defecto; Exposure, ExposureTracker y FireEvacuationControlCenter mantienen AST idéntico.\n- `src/simulation/adaptive_exits.py`: resuelve dependencias sin segundo movimiento y delega decisiones amenazadas a la política preventiva; conserva controlador y cruces.\n- `src/simulation/evacuation_metrics.py`: añade desglose y confirmaciones; compatible con fixtures históricos sin trazas.\n- `src/routing/intelligent_policy.py`: caché geométrica y margen ya comprobado opcional.\n- `src/routing/safe_routing.py`: reutiliza la validación del mismo turno, sin omitir puntos.\n- `src/dcc_app/functional_application.py`: presentación/Debug, HUD y capas.\n- `src/dcc_app/mode_application.py`: hook de viewport, D/cámara y captura opcional; default legacy preservado.\n- `data/functional_scenario.json`: añade solo interior_prediction/presentation; todos los campos anteriores idénticos.\n- `tests/test_second_functional_changes.py`: el ensayo de clic usa el viewport real nuevo en lugar del rectángulo lateral histórico. Conserva las mismas aserciones de selección/bloqueo.\n- `tools/profile_evacuation.py`: añade diagnóstico/memoria de campos después del intervalo cronometrado.\n- `README.md`: ejecución, controles, umbrales y estado.\n\nNo se movieron ni eliminaron archivos. Cambios detectados frente al snapshot previo: "+', '.join(changed)+'.')
 s('21. Tests',f"Suite final: **{tests['scripts']} scripts, {tests['unit_tests']} pruebas unittest, cero fallos, cero omisiones**. Incluye PostgreSQL18.4 temporal y las suites históricas/legacy. Las pruebas nuevas son{new_test_count}: frente/RNG/viento/combustible, escape previo a ignición observada, alternativa/refugio/conectividad, prioridad real E16, métricas confirmadas y límite temporal, traducciones/conteos, D real y caché con peligro/ruta mutables; además refugios libres y espacio para población pendiente, cola de dependencias sin doble paso, SafetyScore solo Debug, teclas +/− y tres pruebas de procedencia que rechazan cambios de backend/datos como si fueran visuales.\n\nComandos:\n\n```powershell\npython tests/test_seventh_functional_changes.py\npython tests/test_sixth_functional_changes.py\npython tests/test_fifth_functional_changes.py\npython tests/test_second_functional_changes.py\n$env:DCC_POSTGRES_BIN = '<directorio PostgreSQL>\\bin'\npython tools/run_tests.py --require-db --output-dir reports/septima_fase/tests_final\npython tools/render_presentation.py\npython tools/profile_evacuation.py --turns 240 --output-dir reports/septima_fase --profile\npython tools/compare_evacuation_modes_v3.py --workers 3\n```\n\nLos logs completos están en tests_final. La suite incluye arranque activo/legacy. Se hicieron primero pruebas relacionadas y luego el conjunto completo. Los reportes iniciales fallidos se conservan separados, no se presentan como aprobados.")
 s('22. Problemas encontrados',"1. El observador nuevo asumía fire_contact_traces en un fixture SimpleNamespace de quinta fase: se añadió fallback vacío para esa interfaz mínima, sin alterar FunctionalSimulation real.\n2. El test de clic de segunda fase calculaba píxeles con el viewport lateral antiguo: se actualizó al viewport de la aplicación, manteniendo aserciones.\n3. El primer harness de captura reutilizaba fuentes después de pygame.quit y podía abortar nativamente. Se corrigió el harness para una sesión SDL por objeto, y D de ida/vuelta dentro del mismo bucle. No se oculta el ensayo fallido.\n4. Se cerró explícitamente el límite de tres turnos de confirmación de escapes para no contar igniciones tardías.\n5. El primer benchmark se detuvo al encontrar incompatibilidades; se preservó en preliminary_before_fixture_compatibility y se reejecutaron los32 episodios finales.\n6. El primer tiempo0.806 superó el objetivo: se perfiló y optimizó validación geométrica, sin bajar precisión ni personas.\n\n7. El primer lote completo conservó47 contactos Intelligent (2.9375 frente a2.5 Traditional). E15 y humo persistente mostraron agrupamiento en refugios con pocas metas. Se ensayó un cuartil de metas libres con espacio según población: E15 pasó9→3 contactos y69→41 incapacitados; humo persistente21→19 contactos con26 incapacitados en ambos. Se incorporó esa política genérica y se reejecutaron los32 episodios. Ese segundo lote aún dio44 contactos (2.75). Se reprodujo la inversión de prioridad y se ensayó una cola de dependencias: S02 pasó12→10 y S16 pasó19→16 contactos, sin segundo paso por alumno. Se incorporó el hook con un único movimiento compartido y se reejecutaron los32 episodios finales. El primer lote/config/fuentes sigue en first_complete_iteration y el segundo en second_complete_iteration; los ensayos dirigidos están etiquetados como experimentos, no se mezclan con el resultado final.\n\nLas pérdidas finales por caso/métrica permanecen visibles en la tabla y CSV. En particular E16 sigue peor que Traditional en contactos: S02=10 frente a4 y S16=16 frente a13; no se declara resuelto ese encierro. A160 turnos Intelligent tiene menos llegadas a reunión y mayor distancia recorrida que Traditional. Es una pérdida de rapidez/directitud a cambio de menor exposición; no se presenta como superior en todas las métricas. Los edificios de salida única siguen siendo una restricción física real. La última ampliación de Debug tuvo una aserción demasiado estricta para float32 (7.499999888 frente a7.5); se corrigió solo la tolerancia a1e-6, se verificaron las38 pruebas nuevas y se repitió la suite completa. El log fallido se conserva en ui_float32_assertion_failure.")
 s('23. Limitaciones',"Modelo didáctico sintético; no predice seguridad de incendios reales. El frente no anticipa sorteos ni cambios futuros de viento, por lo que no garantiza cero contactos. Una ignición inicial o propagación del primer turno sobre un alumno, antes de su primer movimiento, no puede deshacerse con este orden físico. Incapacidad y ralentización siguen restringiendo movimiento. Un refugio interior con conexión geométrica estática puede quedar aislado dinámicamente; no crea una puerta. El criterio de ramificación local reduce callejones evidentes, pero no resuelve todos los cortes topológicos futuros.\n\nEN ZONA SEGURA es presencia móvil en reunión habilitada según el modelo, no certificación. Capturas verificadas a1320×830; tamaños de ventana mucho menores conservan limitaciones de espacio. Debug prioriza diagnóstico y conserva líneas largas del panel histórico. El predictor de viento permanece sintético y no meteorológico real. Los tiempos dependen del hardware y la carga; se separó medición aislada de workers.")
 s('24. Cosas que NO cambiaste',"Grid480×300;1879 alumnos y distribución; física/parámetros de fuego, humo, spotting, vegetación y viento real; predictor Ridge/persistencia; sensores/contratos/target fire_within_2_cells; Persona2/PostgreSQL; reuniones físicas; puertas y orientaciones; máximo una celda/turno; baseA*; pesos de congestión; fórmulaSafetyScore; escenarios Traditional; legacy. Se verificaron31 hashes de fuentes/datos protegidos y todos los valores previos de configuración. hazard_impact.py tuvo un refactor deliberado del movimiento interior; Exposure, ExposureTracker y FireEvacuationControlCenter conservan AST idéntico. La identidad de decisiones Traditional se comprueba además contra las16 ejecuciones originales.\n\nMensaje exacto conservado: «Ninguna tortuga saldrá lastimada durante esta simulación.»\n\nNo se agregaron dependencias. No se hizo push, commit, merge destructivo ni borrado de ramas. Se preservaron cambios previos no committeados, incluidos Chagoya y staging ajeno.")
 s('25. Comandos',"Desde la carpeta principal del repositorio:\n\n```powershell\ncd DisasterCommandCenter\npython main.py\n```\n\nComparación visual tradicional: `python main.py --evacuation-mode traditional`. Legacy: `python main.py --legacy`. En el entorno de esta revisión también se puede ejecutar desde la raíz `.\\.venv\\Scripts\\python.exe DisasterCommandCenter/main.py`. Instalar desde cero según README con `python -m pip install -r requirements.txt`; DB es opcional para la app.\n\nControles visibles: A iniciar; ESPACIO pausa; +/− reproducción; V viento; H humo; D detalles. Clic antes de A selecciona foco, después alumno; rueda zoom; botón derecho desplazar; R reinicia.")
 s('26. Estado final',f"**{state}**\n\nCriterios medidos: `{json.dumps(gates,ensure_ascii=False)}`. Fire contacts medios T/I={t['fire_contacts']['mean']:.4f}/{i['fire_contacts']['mean']:.4f}; rendimiento aislado={perf['seconds_per_turn']:.6f}s/turno. No se declara corregido todo contacto interior si aún existen casos en las trazas. La comparación completa y sus pérdidas se publican sin eliminar escenarios. Antes de ampliar funciones conviene revisar los casos residuales de salida única y validar la presentación en el proyector real.")
 text='# Disaster Command Center — Seventh Functional Changes Feedback\n\n'+'\n'.join(sections)
 assert text.count('\n## ')==26
